import{_ as t,o as r,c as d,X as o}from"./chunks/framework.pSp8ynCZ.js";const u=JSON.parse('{"title":"Errors and crate-root exports","titleTemplate":":title · CellPack Rust","description":"","frontmatter":{},"headers":[],"relativePath":"rust/api/reference-errors.md","filePath":"reference-errors.md"}'),a={name:"rust/api/reference-errors.md"};function c(n,e,i,s,l,p){return r(),d("div",null,[...e[0]||(e[0]=[o('<h1 id="errors-and-crate-root-exports" tabindex="-1">Errors and crate-root exports <a class="header-anchor" href="#errors-and-crate-root-exports" aria-label="Permalink to &quot;Errors and crate-root exports&quot;">​</a></h1><p>The crate has two error domains. Storage, codecs, metadata and runtime use <code>cellpack::Error</code> / <code>cellpack::Result&lt;T&gt;</code>. Loading and planning use <code>cellpack::loader::Error</code> / <code>loader::Result&lt;T&gt;</code>. The root also re-exports <code>CpkFile</code> and <code>CpkWriter</code> for convenience.</p><h2 id="format-codec-and-storage-errors" tabindex="-1">Format, codec, and storage errors <a class="header-anchor" href="#format-codec-and-storage-errors" aria-label="Permalink to &quot;Format, codec, and storage errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Meaning</th><th>Recovery scope</th></tr></thead><tbody><tr><td><code>InvalidInput / InvalidOptions</code></td><td>An argument or declaration violates the API</td><td>Correct inputs/options before retrying</td></tr><tr><td><code>OutputTooSmall</code></td><td>Output extent differs from the required size</td><td>Recompute exact size or capacity</td></tr><tr><td><code>WorkspaceTooSmall</code></td><td>Scratch is undersized</td><td>Allocate the requested number of <code>u64</code> words</td></tr><tr><td><code>OutputTypeTooNarrow</code></td><td>Index/offset type cannot hold a required value</td><td>Use a wider output integer type</td></tr><tr><td><code>RowOutOfRange</code></td><td>Requested row/cell/chunk position is invalid</td><td>Correct the selector and id space</td></tr><tr><td><code>TablesMismatch</code></td><td>Tables belong to different metadata</td><td>Rebuild/bind the correct tables</td></tr><tr><td><code>CorruptMeta / CorruptRecord</code></td><td>An explicitly checked consistency rule failed</td><td>Reject the affected input/output</td></tr><tr><td><code>Io</code></td><td>File operation failed</td><td>Inspect preserved error kind and message</td></tr></tbody></table><p>These errors do not imply every malformed record is checked. Trusted inner-record corruption can violate optimized decoder assumptions. After a failed read/decode, discard potentially partial output.</p><h2 id="loader-and-planner-errors" tabindex="-1">Loader and planner errors <a class="header-anchor" href="#loader-and-planner-errors" aria-label="Permalink to &quot;Loader and planner errors&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variant</th><th>Meaning</th><th>Recovery scope</th></tr></thead><tbody><tr><td><code>Config(String)</code></td><td>Invalid declaration or protocol use</td><td>Correct configuration or call order</td></tr><tr><td><code>Access { position, cell }</code></td><td>Sequence names a cell outside the source</td><td>Fix the generator or registration ranges</td></tr><tr><td><code>Io</code></td><td>OS I/O failure or short read</td><td>Inspect the OS error and input/storage state</td></tr><tr><td><code>CellPack</code></td><td>Wrapped format/codec/storage error</td><td>Preserve and inspect its underlying cause</td></tr><tr><td><code>Plan(String)</code></td><td>Incompatible plan, costs or planning options</td><td>Correct options or recompile for the actual graph</td></tr><tr><td><code>Process(status)</code></td><td>Native process callback failed</td><td>Interpret application-defined status</td></tr><tr><td><code>Accesses(status)</code></td><td>Native sampling callback failed</td><td>Interpret application-defined status</td></tr><tr><td><code>WorkerPanic</code></td><td>A worker or compiler thread panicked</td><td>Fail the run and inspect diagnostics</td></tr><tr><td><code>Busy</code></td><td>Loader or ring is occupied</td><td>Complete/drop prior run and release its slots</td></tr><tr><td><code>Aborted</code></td><td>Cancellation was observed</td><td>Stop this run; identify its originating cause</td></tr></tbody></table><p>A loader failure cancels other participants. Prefer the first non-<code>Aborted</code> error when reporting a failure, rather than replacing it with a secondary cancellation error. Workers are joined before producer error return.</p><p>An aborted ring cannot be prepared again. Allocate a new ring for recovery. A successfully completed ring can be reused after all slots and leases are released and the old run handle is dropped.</p><h2 id="root-interface-index" tabindex="-1">Root interface index <a class="header-anchor" href="#root-interface-index" aria-label="Permalink to &quot;Root interface index&quot;">​</a></h2><h3 id="re-exports" tabindex="-1">Re-exports <a class="header-anchor" href="#re-exports" aria-label="Permalink to &quot;Re-exports&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-CpkFile.html"><code>CpkFile</code></a></td><td>An opened .cpk file.</td></tr><tr><td><a href="/cellpack-docs/rust/api/generated-store-struct-CpkWriter.html"><code>CpkWriter</code></a></td><td>Writes one matrix to a .cpk file. Rows are appended in order; the file is valid only after CpkWriter::finish .</td></tr></tbody></table><h3 id="enums" tabindex="-1">Enums <a class="header-anchor" href="#enums" aria-label="Permalink to &quot;Enums&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-root-enum-Error.html"><code>Error</code></a></td><td>Why an operation failed.</td></tr></tbody></table><h3 id="type-aliases" tabindex="-1">Type Aliases <a class="header-anchor" href="#type-aliases" aria-label="Permalink to &quot;Type Aliases&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Interface</th><th>Responsibility</th></tr></thead><tbody><tr><td><a href="/cellpack-docs/rust/api/generated-root-type-Result.html"><code>Result</code></a></td><td>The crate’s result type.</td></tr></tbody></table>',16)])])}const f=t(a,[["render",c]]);export{u as __pageData,f as default};
